SOURCE='pro/MPL_84_146-193_transcription.tex'
items=[]; entries=[]
def add(n,kind,scans,lines,words,statement,reconstruction,reason,verdict='kept',check='agrees',merge=None):
    ns=n if isinstance(n,list) else [n]
    itemid=f'SA02-{199+ns[0]}'
    if merge is not None:itemid=f'SA02-{199+merge}'
    if merge is None:
        items.append(dict(id=itemid,sources=[f'MPL_84_146-193#{v}' for v in ns],kind=kind,cote='84',scans=scans,lines=[SOURCE+':'+v for v in lines],his_words=words,statement=statement,reconstruction=reconstruction,check=check,check_reason=reason))
    else:
        old=next(x for x in items if x['id']==itemid);old['sources'] +=[f'MPL_84_146-193#{v}' for v in ns]
        for s in scans:
            if s not in old['scans']:old['scans'].append(s)
        old['lines'] += [SOURCE+':'+v for v in lines]
    for j,v in enumerate(ns):entries.append(dict(entry_id=f'MPL_84_146-193#{v}',item_id=itemid,verdict=('merged into '+itemid if merge is not None or j else verdict),reason=reason))

