# Human-selected consolidation of the three pieces of one fourteen-pair list.
def coalesce(chosen,statement,reason):
    keepid=f'SA02-{199+chosen[0]}'; kept=next(x for x in items if x['id']==keepid)
    ids={f'SA02-{199+n}' for n in chosen[1:]}
    for x in list(items):
        if x['id'] in ids:
            kept['sources']+=x['sources'];kept['scans']=sorted(set(kept['scans']+x['scans']));kept['lines']+=x['lines'];items.remove(x)
    kept['statement']=statement;kept['check_reason']=reason
    for x in entries:
        if x['item_id'] in ids:x['item_id']=keepid;x['verdict']='merged into '+keepid;x['reason']=reason
