def write():
    (W/'items.json').write_text(json.dumps(items,ensure_ascii=False,indent=2)+'\n')
    with (W/'entries.tsv').open('w') as f:
        q=csv.DictWriter(f,fieldnames=['entry_id','item_id','verdict','reason'],delimiter='\t');q.writeheader();q.writerows(sorted(entries,key=lambda x:int(x['entry_id'].split('#')[1])))
    print(f'Serialized {len(entries)} read verdicts and {len(items)} items.')
if __name__=='__main__':write()
